const { test } = require('node:test');
const assert = require('node:assert');
const { parseConfig } = require('../src/config');

// parseConfig returns a null-prototype object, which deepStrictEqual rejects
// against an object literal, so compare a spread copy.
const parsed = (text) => ({ ...parseConfig(text) });

test('parses key=value pairs', () => {
  assert.deepStrictEqual(parsed('name=world'), { name: 'world' });
});

test('ignores blank lines and full-line comments', () => {
  assert.deepStrictEqual(parsed('# a comment\n\nname=world\n'), { name: 'world' });
});

test('treats a line with no equals sign as a flag', () => {
  assert.deepStrictEqual(parsed('DEBUG'), { DEBUG: 'true' });
});

test('rejects a line with an empty key', () => {
  assert.throws(() => parseConfig('=orphan'), /missing key/);
});

test('preserves an equals sign inside the value', () => {
  assert.strictEqual(parseConfig('url=http://x/?a=b').url, 'http://x/?a=b');
});

test('trims surrounding whitespace from keys and values', () => {
  assert.deepStrictEqual(parsed('  name  =  world  '), { name: 'world' });
});

test('gives the last occurrence of a duplicated key', () => {
  assert.deepStrictEqual(parsed('a=1\na=2'), { a: '2' });
});

test('does not pollute Object.prototype', () => {
  parseConfig('__proto__=polluted');
  assert.strictEqual({}.polluted, undefined);
  assert.strictEqual(Object.getPrototypeOf(parseConfig('')), null);
});
